import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    def norm_species(x):
        if pd.isna(x):
            return x
        s = str(x).strip()
        low = s.lower()
        mapping = {'adelie': 'Adelie', 'chinstrap': 'Chinstrap', 'gentoo': 'Gentoo', 'gentto': 'Gentoo'}
        return mapping.get(low, s)
    df['species'] = df['species'].map(norm_species)
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    neg = df['flipper_length_mm'] < 0
    df.loc[neg, 'flipper_length_mm'] = df.loc[neg, 'flipper_length_mm'].abs()
    df.loc[(df['flipper_length_mm'] < 170) | (df['flipper_length_mm'] > 235), 'flipper_length_mm'] = np.nan
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', '', regex=False), errors='coerce')
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'flipper_length_mm'])
    out = d.groupby('species')['flipper_length_mm'].mean().to_dict()
    return {str(k): float(v) for k, v in out.items()}
